#' Nest a data.table by group (internal)
#'
#' Shared by w2l_nest() and c2p_nest(). `group_by` may be NULL (one group).
#'
#' @param dt        A data.table ready for nesting.
#' @param group_by  Character vector of grouping columns, or NULL.
#' @param sd_cols   Columns stored inside each nested object.
#' @param out_type "dt" or "df".
#' @return A data.table with the group keys and a `data` list-column.
#' @noRd
.nest_by_group <- function(dt, group_by, sd_cols, out_type) {
  . <- NULL
  if (out_type == "dt") {
    dt[, .(data = list(.SD)), by = group_by, .SDcols = sd_cols]
  } else {
    # .SD is a re-used buffer inside grouping, so a copy is required anyway;
    # setDF() then converts that private copy in place.
    dt[, .(data = list(data.table::setDF(data.table::copy(.SD)))),
       by = group_by, .SDcols = sd_cols]
  }
}

#' Reshape Wide Data to Long Format and Nest by Specified Columns
#'
#' @description
#' `w2l_nest` reshapes a wide-format `data.frame` or `data.table` into long
#' format, then nests the result by `name` (the pivoted column identifier) and
#' any optional grouping variables supplied via `by`. Each row of the returned
#' table contains a nested `data.table` or `data.frame` in the `data` list-column.
#'
#' @param data `data.frame` or `data.table`. Wide-format input dataset.
#'   The input object is never modified: a `data.frame` is converted with
#'   `as.data.table()`, a `data.table` is read as-is.
#' @param cols `numeric` or `character`. Columns to pivot from wide to long,
#'   specified as integer indices or column names. Default `NULL`: when `NULL`,
#'   `by` must be provided and the function performs a pure nest operation
#'   (no melting).
#' @param by `numeric` or `character`. Additional grouping variables for
#'   hierarchical nesting, specified as integer indices or column names.
#'   Default `NULL`.
#' @param out_type `character`. Class of each nested subset:
#'   `"dt"` for `data.table` (default) or `"df"` for `data.frame`.
#'
#' @return A `data.table` with one row per combination of `name` (and `by`
#'   levels, if provided). The `data` list-column holds the corresponding
#'   nested `data.table` or `data.frame` for each group. Grouping key columns
#'   are never duplicated inside the nested objects.
#'
#' @details
#' **Column resolution:** both `cols` and `by` accept either integer column
#' positions or character column names. Out-of-bounds indices and unknown names
#' are caught early with informative error messages.
#'
#' **Overlap guard:** if any column appears in both `cols` and `by`, the
#' function stops with an error before attempting to melt, preventing silent
#' structural corruption.
#'
#' **Factor-free melting:** `melt()` is called with `variable.factor = FALSE`
#' so the `name` column is always `character`, avoiding unexpected factor-level
#' ordering in downstream grouping operations.
#'
#' **No side effects:** earlier versions called `setDT()` on the argument,
#' which silently turned the caller's `data.frame` into a `data.table`. The
#' input is now left untouched.
#'
#' **Memory efficiency:** `.SDcols` restricts `.SD` to non-key columns, so
#' grouping keys are never stored redundantly inside each nested object.
#'
#' @note
#' \itemize{
#'   \item Passing an empty table (0 rows) triggers a `warning()` and returns
#'         a 0-row table with the regular column structure
#'         (`name`, the `by` columns and `data`).
#'   \item `name` and `value` are reserved for the long format; `data` must
#'         not contain other columns with these names.
#'   \item `cols` and `by` must not overlap; overlapping columns will raise
#'         an error.
#'   \item `out_type` values other than `"dt"` or `"df"` raise an error.
#' }
#'
#' @seealso `tidytable::nest_by()` for a tidyverse-style equivalent.
#'
#' @import data.table
#' @export
#' @examples
#' # Example: Wide to long format nesting demonstrations
#'
#' # Example 1: Basic nesting by group
#' w2l_nest(
#'   data = iris,                    # Input dataset
#'   by = "Species"                  # Group by Species column
#' )
#'
#' # Example 2: Nest specific columns with numeric indices
#' w2l_nest(
#'   data = iris,                    # Input dataset
#'   cols = 1:4,                   # Select first 4 columns to nest
#'   by = "Species"                  # Group by Species column
#' )
#'
#' # Example 3: Nest specific columns with column names
#' w2l_nest(
#'   data = iris,                    # Input dataset
#'   cols = c("Sepal.Length",        # Select columns by name
#'            "Sepal.Width",
#'            "Petal.Length"),
#'   by = 5                          # Group by column index 5 (Species)
#' )
#' # Returns similar structure to Example 2
w2l_nest <- function(data, cols = NULL, by = NULL, out_type = "dt") {

  # -- 1. Input validation ----------------------------------------------------
  if (!is.data.frame(data))
    stop("`data` must be a data.frame or a data.table.", call. = FALSE)
  .check_choice(out_type, c("dt", "df"), "out_type")

  # Never touch the caller's object: setDT() would change its class by
  # reference. as.data.table() is only called for non-data.table input;
  # a data.table is used as-is because nothing below modifies it.
  dt <- if (data.table::is.data.table(data)) data else data.table::as.data.table(data)
  data_names <- names(dt)

  # -- 2. Resolve columns -----------------------------------------------------
  by <- .resolve_cols(by, data_names, "by", allow_null = TRUE)
  if (is.null(cols)) {
    if (is.null(by))
      stop("When `cols` is NULL, `by` must be provided.", call. = FALSE)
  } else {
    cols  <- .resolve_cols(cols, data_names, "cols")
    overlap <- intersect(cols, by)
    if (length(overlap) > 0L)
      stop("`cols` and `by` share column(s), which would corrupt the melt structure: ",
           paste(overlap, collapse = ", "), call. = FALSE)
    if (any(c("name", "value") %chin% setdiff(data_names, cols)))
      stop("`data` already contains a column named 'name' or 'value' that is not ",
           "in `cols`; rename it first, as these names are used for the long format.",
           call. = FALSE)
  }

  # -- 3. Empty input: return a 0-row table with the regular structure --------
  if (nrow(dt) == 0L) {
    warning("`data` has 0 rows; returning an empty nested data.table.", call. = FALSE)
    out <- c(if (!is.null(cols)) list(name = character(0L)),
             if (length(by)) as.list(dt[0L, by, with = FALSE]),
             list(data = list()))
    return(data.table::setDT(out)[])
  }

  # -- 4. Pure nest mode (no melting) -----------------------------------------
  if (is.null(cols)) {
    return(.nest_by_group(dt, group_by = by,
                          sd_cols = setdiff(data_names, by),
                          out_type = out_type))
  }

  # -- 5. Wide-to-long, then nest by name (+ by) ------------------------------
  melted <- data.table::melt(
    dt,
    measure.vars    = cols,
    variable.name   = "name",
    value.name      = "value",
    variable.factor = FALSE
  )
  group_keys <- c("name", by)
  .nest_by_group(melted, group_by = group_keys,
                 sd_cols = setdiff(names(melted), group_keys),
                 out_type = out_type)
}
